function Login({done}:{done:(t:string,u:User)=>void}){
 const[l,setL]=useState(""),[p,setP]=useState(""),[code,setCode]=useState(""),[challenge,setChallenge]=useState<string|null>(null),[busy,setBusy]=useState(false),[err,setErr]=useState("");
 async function go(renewEmailCode=false){if(!l.trim()||!p)return setErr("Kullanıcı adı/e-posta ve şifre gerekli.");setBusy(true);setErr("");try{const r=await login(l,p,renewEmailCode);if(!r.access_token&&r.challenge_token){setChallenge(r.challenge_token);return}if(!r.access_token)throw new Error("E-posta doğrulaması gerekiyor.");const me=await getMe(r.access_token);await SecureStore.setItemAsync("dentalai_token",r.access_token);done(r.access_token,me.user)}catch(e){setErr(e instanceof Error?e.message:"Giriş başarısız.")}finally{setBusy(false)}}
 async function verify(){if(!challenge||!/^[0-9]{6}$/.test(code))return setErr("6 haneli doğrulama kodunu girin.");setBusy(true);setErr("");try{const r=await verifyEmail(challenge,code);const me=await getMe(r.access_token);await SecureStore.setItemAsync("dentalai_token",r.access_token);done(r.access_token,me.user)}catch(e){setErr(e instanceof Error?e.message:"Doğrulama başarısız.")}finally{setBusy(false)}}
 return <KeyboardAvoidingView style={s.login} behavior={Platform.OS==="ios"?"padding":undefined}><ScrollView contentContainerStyle={s.loginInner}><Logo/><Text style={s.title}>DENTAL AI</Text><Text style={s.sub}>{challenge?"E-posta adresinize gönderilen kodu girin.":"Kliniğin cebinde. Hızlı, sade, güvenli."}</Text><View style={s.form}>{challenge?<><Text style={s.label}>6 haneli doğrulama kodu</Text><TextInput style={s.input} value={code} onChangeText={setCode} keyboardType="number-pad" inputMode="numeric" maxLength={6} autoComplete="one-time-code"/><Text style={s.cardSub}>Kod 10 dakika geçerlidir ve yalnızca bir kez kullanılabilir. Kodun süresi dolduysa aşağıdaki yenileme düğmesini kullanın.</Text>{!!err&&<Text style={s.err}>{err}</Text>}<Pressable style={s.primary} onPress={verify} disabled={busy}>{busy?<ActivityIndicator color="#fff"/>:<Text style={s.primaryText}>E-postayı Doğrula</Text>}</Pressable><Pressable disabled={busy} onPress={()=>{setChallenge(null);setCode("");setErr("")}}><Text style={s.cardSub}>Giriş ekranına dön</Text></Pressable><Pressable disabled={busy} onPress={()=>{setCode("");void go(true)}}><Text style={s.cardSub}>Süresi dolan kodu yenile</Text></Pressable></>:<><Text style={s.label}>Kullanıcı adı veya e-posta</Text><TextInput style={s.input} placeholder="Hesabın" placeholderTextColor={C.muted} autoCapitalize="none" value={l} onChangeText={setL}/><Text style={s.label}>Şifre</Text><TextInput style={s.input} placeholder="Şifren" placeholderTextColor={C.muted} secureTextEntry value={p} onChangeText={setP}/>{!!err&&<Text style={s.err}>{err}</Text>}<Pressable style={s.primary} onPress={()=>void go()} disabled={busy}>{busy?<ActivityIndicator color="#fff"/>:<Text style={s.primaryText}>Giriş Yap</Text>}</Pressable><Pressable accessibilityRole="link" accessibilityLabel="Üye Ol" onPress={()=>{void Linking.openURL("https://dentalai.tr/register").catch(()=>setErr("Kayıt sayfası açılamadı."))}} style={{paddingVertical:16,alignItems:"center"}}><Text style={{color:C.navy,fontWeight:"800",fontSize:15}}>Hesabın yok mu? Üye Ol</Text></Pressable></>}</View></ScrollView></KeyboardAvoidingView>
}
